/**
 * Splits a URI reference string into its components. Each optional
 * component carries a `*Present` flag alongside its (possibly empty) text.
 */
export function parseUriReference(text) {
  let rest = text
  let schemePresent = false
  let scheme = ''

  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === ':') {
      schemePresent = true
      scheme = rest.slice(0, i)
      rest = rest.slice(i + 1)
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }

  let authorityPresent = false
  let authority = ''
  if (rest.startsWith('//')) {
    authorityPresent = true
    let i = 2
    while (i < rest.length && rest[i] !== '/' && rest[i] !== '?' && rest[i] !== '#') i++
    authority = rest.slice(2, i)
    rest = rest.slice(i)
  }

  let i = 0
  while (i < rest.length && rest[i] !== '?' && rest[i] !== '#') i++
  const path = rest.slice(0, i)
  rest = rest.slice(i)

  let queryPresent = false
  let query = ''
  if (rest[0] === '?') {
    let j = 1
    while (j < rest.length && rest[j] !== '#') j++
    queryPresent = true
    query = rest.slice(1, j)
    rest = rest.slice(j)
  }

  let fragmentPresent = false
  let fragment = ''
  if (rest[0] === '#') {
    fragmentPresent = true
    fragment = rest.slice(1)
  }

  return {
    schemePresent,
    scheme,
    authorityPresent,
    authority,
    path,
    queryPresent,
    query,
    fragmentPresent,
    fragment,
  }
}

/**
 * Splits an authority string into userinfo, host and port, by the rule that
 * the userinfo is everything before the last `@`, the port is everything
 * after the first `:` that follows the last `]`, and the host lies between.
 */
export function splitAuthority(authority) {
  let userinfoPresent = false
  let userinfo = ''
  let rest = authority

  const lastAt = authority.lastIndexOf('@')
  if (lastAt !== -1) {
    userinfoPresent = true
    userinfo = authority.slice(0, lastAt)
    rest = authority.slice(lastAt + 1)
  }

  const lastBracket = rest.lastIndexOf(']')
  const searchStart = lastBracket === -1 ? 0 : lastBracket + 1
  const colonIndex = rest.indexOf(':', searchStart)

  let host
  let portPresent = false
  let port = ''
  if (colonIndex !== -1) {
    host = rest.slice(0, colonIndex)
    portPresent = true
    port = rest.slice(colonIndex + 1)
  } else {
    host = rest
  }

  return { userinfoPresent, userinfo, host, portPresent, port }
}

/**
 * Removes `.` and `..` path segments per RFC 3986 section 5.2.4.
 */
export function removeDotSegments(path) {
  let input = path
  let output = ''

  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = removeLastSegment(output)
    } else if (input === '/..') {
      input = '/'
      output = removeLastSegment(output)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx
      if (input[0] === '/') {
        idx = input.indexOf('/', 1)
      } else {
        idx = input.indexOf('/')
      }
      if (idx === -1) idx = input.length
      output += input.slice(0, idx)
      input = input.slice(idx)
    }
  }

  return output
}

function removeLastSegment(output) {
  const idx = output.lastIndexOf('/')
  return idx === -1 ? '' : output.slice(0, idx)
}
