{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-eEt2M1/src/resolve.js","content":"/**
 * Resolution of a URI reference against a base, by RFC 3986 section 5.2.2
 * in its strict form: a reference that repeats the base's scheme is still
 * treated as an absolute URI, never merged with the base.
 */

import { removeDotSegments } from './uri-reference.js'

/**
 * Resolves `ref` against `base`, both already-parsed URI references, and
 * returns the target as an unnormalized set of components.
 */
export function resolveReference(base, ref) {
  let schemePresent
  let scheme
  let authorityPresent
  let authority
  let path
  let queryPresent
  let query

  if (ref.schemePresent) {
    schemePresent = true
    scheme = ref.scheme
    authorityPresent = ref.authorityPresent
    authority = ref.authority
    path = removeDotSegments(ref.path)
    queryPresent = ref.queryPresent
    query = ref.query
  } else if (ref.authorityPresent) {
    schemePresent = base.schemePresent
    scheme = base.scheme
    authorityPresent = true
    authority = ref.authority
    path = removeDotSegments(ref.path)
    queryPresent = ref.queryPresent
    query = ref.query
  } else {
    schemePresent = base.schemePresent
    scheme = base.scheme
    authorityPresent = base.authorityPresent
    authority = base.authority

    if (ref.path === '') {
      path = base.path
      if (ref.queryPresent) {
        queryPresent = true
        query = ref.query
      } else {
        queryPresent = base.queryPresent
        query = base.query
      }
    } else if (ref.path.startsWith('/')) {
      path = removeDotSegments(ref.path)
      queryPresent = ref.queryPresent
      query = ref.query
    } else {
      path = removeDotSegments(mergePaths(base, ref.path))
      queryPresent = ref.queryPresent
      query = ref.query
    }
  }

  return {
    schemePresent,
    scheme,
    authorityPresent,
    authority,
    path,
    queryPresent,
