{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-eEt2M1/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { CliError } from './cli-error.js'
import { normalizeComponents } from './normalize.js'
import { resolveReference } from './resolve.js'
import { parseUriReference } from './uri-reference.js'

function readStdin(stream) {
  return new Promise((resolve, reject) => {
    const chunks = []
    stream.on('data', (chunk) => chunks.push(chunk))
    stream.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    stream.on('error', reject)
  })
}

function splitRecords(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function normalizeRecord(line, lineNumber) {
  const components = parseUriReference(line)
  return normalizeComponents(components, lineNumber)
}

function resolveRecord(line, lineNumber) {
  const spaceIndex = line.indexOf(' ')
  if (spaceIndex === -1) {
    throw new CliError(`line ${lineNumber}: expected a base and a reference`)
  }
  const baseText = line.slice(0, spaceIndex)
  const refText = line.slice(spaceIndex + 1)

  const base = parseUriReference(baseText)
  if (!base.schemePresent) {
    throw new CliError(`line ${lineNumber}: the base has no scheme`)
  }
  const ref = parseUriReference(refText)
  const target = resolveReference(base, ref)
  return normalizeComponents(target, lineNumber)
}

async function main() {
  const [mode] = process.argv.slice(2)
  if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const input = await readStdin(process.stdin)
  const records = splitRecords(input)
  const process_ = mode === 'normalize' ? normalizeRecord : resolveRecord

  const results = []
  try {
    for (let i = 0; i < records.length; i++) {
      results.push(process_(records[i], i + 1))
    }
  } catch (error) {
    if (error instanceof CliError) {
      process.stderr.write(`error: ${error.message}\n`)
      process.exit(2)
    }
    throw error
  }

  if (results.length > 0) {
    process.stdout.write(results.join('\n') + '\n')
  }
  process.exit(0)
}

main()
"}

